CREATE TABLE IF NOT EXISTS rol (id SERIAL PRIMARY KEY, nombre TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS usuario (id SERIAL PRIMARY KEY, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, activo BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS usuario_rol (usuario_id INTEGER NOT NULL REFERENCES usuario(id), rol_id INTEGER NOT NULL REFERENCES rol(id), PRIMARY KEY(usuario_id, rol_id));
CREATE TABLE IF NOT EXISTS paciente (id SERIAL PRIMARY KEY, usuario_id INTEGER NOT NULL UNIQUE REFERENCES usuario(id), nombre TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS profesional (id SERIAL PRIMARY KEY, usuario_id INTEGER NOT NULL UNIQUE REFERENCES usuario(id), nombre TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS disponibilidad (id SERIAL PRIMARY KEY, profesional_id INTEGER NOT NULL REFERENCES profesional(id), franja_inicio TIMESTAMPTZ NOT NULL, franja_fin TIMESTAMPTZ NOT NULL, CHECK (franja_fin > franja_inicio), UNIQUE(profesional_id, franja_inicio));
CREATE TABLE IF NOT EXISTS cita (id SERIAL PRIMARY KEY, paciente_id INTEGER NOT NULL REFERENCES paciente(id), profesional_id INTEGER NOT NULL REFERENCES profesional(id), franja_inicio TIMESTAMPTZ NOT NULL, franja_fin TIMESTAMPTZ NOT NULL, estado TEXT NOT NULL CHECK (estado IN ('scheduled','attended','cancelled','no_show')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS cita_active_slot_uq ON cita(profesional_id, franja_inicio) WHERE estado <> 'cancelled';
CREATE INDEX IF NOT EXISTS cita_patient_idx ON cita(paciente_id, franja_inicio);
CREATE INDEX IF NOT EXISTS cita_professional_idx ON cita(profesional_id, franja_inicio);
CREATE INDEX IF NOT EXISTS cita_state_idx ON cita(estado);
CREATE TABLE IF NOT EXISTS encuentro (id SERIAL PRIMARY KEY, cita_id INTEGER NOT NULL REFERENCES cita(id), version INTEGER NOT NULL CHECK(version > 0), reemplaza_id INTEGER REFERENCES encuentro(id), notes TEXT NOT NULL, diagnosis TEXT NOT NULL, author_id INTEGER NOT NULL REFERENCES profesional(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(cita_id, version));
CREATE TABLE IF NOT EXISTS adjunto (id SERIAL PRIMARY KEY, encuentro_id INTEGER NOT NULL REFERENCES encuentro(id), filename TEXT NOT NULL, content_type TEXT NOT NULL, storage_path TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS auditoria (id SERIAL PRIMARY KEY, usuario_id INTEGER REFERENCES usuario(id), action TEXT NOT NULL, resource_type TEXT NOT NULL, resource_id TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS availability_filter_idx ON disponibilidad(profesional_id, franja_inicio);
CREATE INDEX IF NOT EXISTS encounter_appointment_idx ON encuentro(cita_id, version);
CREATE INDEX IF NOT EXISTS attachment_encounter_idx ON adjunto(encuentro_id);
CREATE INDEX IF NOT EXISTS audit_time_idx ON auditoria(created_at, usuario_id, action);
INSERT INTO rol(nombre) VALUES ('patient'),('professional'),('staff'),('admin') ON CONFLICT DO NOTHING;
